def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    turn = max(-1.0, min(1.0, b / 30.0))
    if d < 0.8:
        fwd = 0.6
    else:
        fwd = 1.0
    if abs(b) > 90:
        fwd = -0.3
        turn = 1.0 if b > 0 else -1.0
    left = fwd - turn
    right = fwd + turn
    return (max(-1.0, min(1.0, left)), max(-1.0, min(1.0, right)))

