def drive(me, enemy, arena):
    eh = radians(enemy.heading)
    lx, ly = -sin(eh), cos(eh)
    rx, ry = -lx, -ly
    dl = hypot(me.x - (enemy.x + 0.7 * lx), me.y - (enemy.y + 0.7 * ly))
    dr = hypot(me.x - (enemy.x + 0.7 * rx), me.y - (enemy.y + 0.7 * ry))
    if dl < dr:
        tx, ty = enemy.x + 0.7 * lx, enemy.y + 0.7 * ly
    else:
        tx, ty = enemy.x + 0.7 * rx, enemy.y + 0.7 * ry
    d = distance_to(enemy.x, enemy.y)
    if d < 1.6:
        tx, ty = enemy.x, enemy.y
    b = bearing_to(tx, ty)
    turn = max(-1.0, min(1.0, b / 25.0))
    fwd = max(0.0, cos(radians(b)))
    if abs(b) > 120:
        fwd = 0.0
    left = fwd - turn
    right = fwd + turn
    return (max(-1.0, min(1.0, left)), max(-1.0, min(1.0, right)))

